def copiar_evidencias(apps, schema_editor):
    """La foto única de antes pasa a ser la primera evidencia de la tarea."""
    Tarea = apps.get_model("desempeno", "Tarea")
    Evidencia = apps.get_model("desempeno", "EvidenciaArchivo")
    for tarea in Tarea.objects.exclude(evidencia_archivo="").exclude(evidencia_archivo__isnull=True):
        nombre = tarea.evidencia_archivo.name
        Evidencia.objects.create(tarea=tarea, archivo=nombre, nombre_original=nombre.rsplit("/", 1)[-1],
                                 subido_por=tarea.colaborador)
    Configuracion = apps.get_model("desempeno", "ConfiguracionDesempeno")
    if not Configuracion.objects.exists():
        Configuracion.objects.create(tramos_bono=[{"desde": 90, "porcentaje": 10}, {"desde": 80, "porcentaje": 5}])


